// ReSharper disable RedundantNameQualifier

namespace RonSijm.FluidHumidifier.Factories.EKS;

public class ClusterFactory(string resourceName = null, Action<Humidifier.EKS.Cluster> factoryAction = null) : ResourceFactory<Humidifier.EKS.Cluster>(resourceName)
{

    internal List<InnerClusterEncryptionConfigFactory> EncryptionConfigFactories { get; set; } = [];

    internal InnerClusterAccessConfigFactory AccessConfigFactory { get; set; }

    internal InnerClusterKubernetesNetworkConfigFactory KubernetesNetworkConfigFactory { get; set; }

    internal InnerClusterControlPlaneScalingConfigFactory ControlPlaneScalingConfigFactory { get; set; }

    internal InnerClusterOutpostConfigFactory OutpostConfigFactory { get; set; }

    internal InnerClusterLoggingFactory LoggingFactory { get; set; }

    internal InnerClusterRollbackConfigFactory RollbackConfigFactory { get; set; }

    internal InnerClusterComputeConfigFactory ComputeConfigFactory { get; set; }

    internal InnerClusterStorageConfigFactory StorageConfigFactory { get; set; }

    internal InnerClusterKubeApiServerConfigFactory KubeApiServerConfigFactory { get; set; }

    internal InnerClusterZonalShiftConfigFactory ZonalShiftConfigFactory { get; set; }

    internal InnerClusterKubeControllerManagerConfigFactory KubeControllerManagerConfigFactory { get; set; }

    internal InnerClusterUpgradePolicyFactory UpgradePolicyFactory { get; set; }

    internal InnerClusterRemoteNetworkConfigFactory RemoteNetworkConfigFactory { get; set; }

    internal InnerClusterCertificateAuthorityFactory CertificateAuthorityFactory { get; set; }

    internal InnerClusterKubeSchedulerConfigFactory KubeSchedulerConfigFactory { get; set; }

    internal InnerClusterResourcesVpcConfigFactory ResourcesVpcConfigFactory { get; set; }

    protected override Humidifier.EKS.Cluster Create()
    {
        var clusterResult = CreateCluster();
        factoryAction?.Invoke(clusterResult);

        return clusterResult;
    }

    private Humidifier.EKS.Cluster CreateCluster()
    {
        var clusterResult = new Humidifier.EKS.Cluster
        {
            GivenName = InputResourceName,
        };

        return clusterResult;
    }
    public override void CreateChildren(Humidifier.EKS.Cluster result)
    {
        base.CreateChildren(result);

        result.EncryptionConfig = EncryptionConfigFactories.Any() ? EncryptionConfigFactories.Select(x => x.Build()).ToList() : null;
        result.AccessConfig ??= AccessConfigFactory?.Build();
        result.KubernetesNetworkConfig ??= KubernetesNetworkConfigFactory?.Build();
        result.ControlPlaneScalingConfig ??= ControlPlaneScalingConfigFactory?.Build();
        result.OutpostConfig ??= OutpostConfigFactory?.Build();
        result.Logging ??= LoggingFactory?.Build();
        result.RollbackConfig ??= RollbackConfigFactory?.Build();
        result.ComputeConfig ??= ComputeConfigFactory?.Build();
        result.StorageConfig ??= StorageConfigFactory?.Build();
        result.KubeApiServerConfig ??= KubeApiServerConfigFactory?.Build();
        result.ZonalShiftConfig ??= ZonalShiftConfigFactory?.Build();
        result.KubeControllerManagerConfig ??= KubeControllerManagerConfigFactory?.Build();
        result.UpgradePolicy ??= UpgradePolicyFactory?.Build();
        result.RemoteNetworkConfig ??= RemoteNetworkConfigFactory?.Build();
        result.CertificateAuthority ??= CertificateAuthorityFactory?.Build();
        result.KubeSchedulerConfig ??= KubeSchedulerConfigFactory?.Build();
        result.ResourcesVpcConfig ??= ResourcesVpcConfigFactory?.Build();
    }

} // End Of Class

